import {STEAM_JOBS} from './steam-data.js';
import {steamState,steamStatus} from './steam.js';
import {ITEMS} from './survival.js';
const bag=items=>Object.entries(items).map(([k,n])=>ITEMS[k].name+' ×'+n).join('、');
export function steamPanel(b){const m=steamState(b);return`<section class="steam-panel"><h3>木柴驱动的第一座工坊</h3><p>${steamStatus(b)} · 已完成 ${m.batches} 批<br>余热 ${Math.ceil(m.heat)}/24 秒，达到每种产物 20 件后停止开新单。</p><p>先在下方存入原料和额外的木柴。每 1 木材提供 24 秒加工热量；锅炉循环冷凝水，不额外管理水条。每批生态 −0.1，补种可以恢复。机器人可把这里设为搬运起终点。</p><div class="robot-actions"><button class="primary" data-steam="toggle" data-steam-id="${b.id}">${m.enabled?'暂停加工':'启动工坊'}</button><button class="secondary" data-steam="cool" data-steam-id="${b.id}" ${m.job?'disabled':''}>停机排余热</button></div><details open><summary>选择生产线 · 在制品不可改配方</summary><div class="community-realms">${Object.entries(STEAM_JOBS).map(([id,r])=>`<article><b>${r.name}</b><p>${bag(r.cost)} → ${bag(r.drop)}<br>${r.seconds} 秒 · 燃料另计</p><button class="secondary" data-steam="recipe" data-steam-id="${b.id}" data-value="${id}" ${m.job||m.recipe===id?'disabled':''}>${m.recipe===id?'当前配方':'切换配方'}</button></article>`).join('')}</div></details><p class="subtle">只推进当前地图，阅读面板、暂停或离线不计时。停机保留订单，满仓不会吞掉产物；取空并排余热后才可拆除。五级晶能自动装配台仍保留更多高级配方。</p></section>`;}
